select 'contracting', 'ALEC Engineering & Contracting LLC (ALEC Holdings)', 'ALEC Engineering & Contracting LLC (ALEC Holdings)', 'دبي', 'دبي مارينا', '+971 4 429 0599', 'https://www.alec.ae', 1999, 'مقاول إنشاءات يقدم البناء وأعمال MEP والتشطيبات الداخلية وحلول الطاقة ومراكز البيانات وتأجير المعدات.', 'https://alec.ae/about', 'تأسست عام 1999 شراكةً بين مجموعة الجابر وشركة Grinaker LTA الجنوب أفريقية، وأصبحت عام 2017 تابعة لمؤسسة دبي للاستثمارات الحكومية. غيّرت هويتها عام 2025 إلى ALEC Holdings.', 'https://cdn.prod.website-files.com/645c81de0e35a9590f9a3dc0/6a7dac00dc4bd892da57aa19_ALEC_alec-holdings_logo_Master.svg', 'info@alec.ae', 'مارينا بلازا، مكتب 3601، دبي مارينا، دبي، ص.ب 27639', null, array['مينا السلام', 'مردف سيتي سنتر', 'الكونكورس A وD – مطار دبي الدولي', 'بلووترز ريتيل', 'ون زعبيل']::text[], 'يذكر الموقع أن المؤسس ونائب الرئيس كيرون بيتر تايلور أشرف خلال قيادته على أكثر من 11,000 موظف متخصص.', true
where not exists (select 1 from public.service_providers where category = 'contracting' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('ALEC Engineering & Contracting LLC (ALEC Holdings)'));
