select 'engineering', 'National Engineering Bureau (NEB)', 'National Engineering Bureau (NEB)', 'دبي', 'عود ميثاء', '+971 4 324 2020', 'https://www.neb.ae', 1984, 'استشارات هندسية تشمل التصميم المعماري والهندسة والإشراف وإدارة المشاريع لقطاعات سكنية وتجارية وفندقية وتعليمية.', 'https://www.neb.ae/our-offices/', 'مكتب استشارات هندسية مقره دبي منذ عام 1984، يقدم حلول التصميم المعماري والهندسة والإشراف وإدارة المشاريع. عضو في مجلس المباني الشاهقة والموئل الحضري (CTBUH) منذ 2013 حسب موقعه.', 'https://www.neb.ae/wp-content/uploads/2020/01/neb-logo.png', 'info@neb.ae', 'مكتب 304، مكاتب عود ميثاء، مبنى سيتي بنك، دبي، الإمارات العربية المتحدة', null, array['برج مارينا 101 في دبي', 'مبنى مجلس دبي الرياضي', 'برايم بزنس سنتر', 'تعاونية الاتحاد في موتور سيتي', 'مدينة الطاقة في قطر']::text[], 'يضم المكتب أكثر من 500 معماري ومهندس ومدير مشاريع في الإمارات، ويرأسه الرئيس التنفيذي جميل جادالله ناجي.', true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('National Engineering Bureau (NEB)'));
