select 'engineering', 'Godwin Austen Johnson (GAJ)', 'Godwin Austen Johnson (GAJ)', 'أبوظبي', 'مصفح', '+971 2 672 0012', 'https://www.godwinaustenjohnson.com', 1989, 'مكتب عمارة متعدد التخصصات لمشاريع تجارية وسكنية وتعليمية وترفيهية وفندقية.', 'https://www.godwinaustenjohnson.com/contact-us', 'مكتب عمارة متعدد التخصصات أسسه رئيس مجلس الإدارة براين جونسون عام 1989، ويعمل في مشاريع تجارية وسكنية وتعليمية وترفيهية وفندقية. له حضور في الإمارات والمملكة المتحدة والهند وأفريقيا.', 'https://www.godwinaustenjohnson.com/hubfs/GODWIN%20Austen%20johnson.svg', 'mail@gaj-uae.ae', 'مكتب 113، طابق الميزانين، مركز وورك هب للأعمال، الشارع السادس، M21 مصفح، أبوظبي', null, array['نادي خور دبي للغولف', 'مركز جعفر في كلية دبي', 'فندق وارنر براذرز أبوظبي', 'مساكن مدينة جميرا', 'فندق دبل تري باي هيلتون الشارقة']::text[], 'أسسه رئيس مجلس الإدارة براين جونسون، ويديره المدير العام جيسون بيرنسايد.', true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Godwin Austen Johnson (GAJ)'));
