select 'engineering', 'Dewan Architects + Engineers', 'Dewan Architects + Engineers', 'الشارقة', 'التعاون', '+971 6 599 6400', 'https://www.dewan.ae', null, 'شركة عمارة وهندسة وتخطيط تقدم التصميم المعماري والهندسي لمشاريع سكنية وفندقية وتجارية.', 'https://www.dewan.ae/contact', 'شركة عمارة وهندسة وتخطيط تعمل في قطاع التصميم المعماري والهندسي في الشرق الأوسط منذ قرابة ثلاثة عقود حسب موقعها. لها مكاتب في أبوظبي ودبي والشارقة ورأس الخيمة إضافة إلى مكاتب خارج الدولة.', 'https://www.dewan.ae/images/logos/dewan-logo.png', 'sharjah@dewan-architects.com', 'ص.ب 1216، مكتب 01-134، شارع التعاون، الشارقة', null, array['مدى ريزيدنسز في وسط مدينة دبي', 'ريكسوس مارينا أبوظبي', 'مركز الفجيرة للأعمال', 'سنترال بارك في سيتي ووك بدبي', 'برج بني ياس']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'الشارقة' and lower(coalesce(name_en, name_ar)) = lower('Dewan Architects + Engineers'));
