select 'engineering', 'Dar Al-Handasah', 'Dar Al-Handasah', 'عجمان', null, '+971 6 742 4532', 'https://www.dar.com', null, 'استشارات في التصميم والتخطيط والهندسة وإدارة المشاريع للمباني والبنية التحتية والنقل والمياه.', 'https://www.dar.com/contact/region/middle-east', 'شركة استشارات تقدم التصميم والتخطيط والهندسة واستشارات الاستدامة وإدارة المشاريع للمباني والمدن والنقل والبنية التحتية والمياه والبيئة. وهي العضو المؤسس لمجموعة سدارة، ولها أربعة مكاتب في الإمارات.', null, null, 'أبراج الديوان، البرج B، مكتب 2101، شارع الشيخ راشد بن حميد، ص.ب 4002، عجمان', null, array['مبنيان في خور الراحة بأبوظبي', 'الكونكورس C في مطار دبي الدولي']::text[], 'يضم أكثر من 10,700 متخصص في مكاتب حول العالم، ومؤسسه كمال الشاعر حسب موقع الشركة.', true
