select 'interior', 'Algedra Interior Design', 'Algedra Interior Design', 'دبي', 'أبراج بحيرات جميرا', '+971 4 363 9703', 'https://algedra.ae', 2013, 'تصميم داخلي ومعماري وتنفيذ أعمال التشطيب الداخلي للفلل والقصور والمكاتب والمنشآت الفندقية.', 'https://algedra.ae/en/contact-us', 'شركة تصميم داخلي في دبي تأسست عام 2013 بالشراكة بين م. طارق سكيك والرئيس التنفيذي مهاب أيوب. تقدم التصميم الداخلي والمعماري والخارجي وتصميم الحدائق وأعمال التشطيب، وتذكر أنها أنجزت أكثر من 500 مشروع سكني وتجاري وفندقي، ولها مكتب في إسطنبول.', 'https://algedra.ae/_next/static/media/logo.6ab126f4.png', 'hello@algedra.ae', 'مكتب 1501، برج JBC 3 – المجمع Y، أبراج بحيرات جميرا، دبي', null, array['فيلا سيغنتشر في دبي هيلز', 'فلل خاصة في دبي هيلز', 'تشطيب قصور في مدينة محمد بن راشد', 'تجديد بنتهاوس في وسط مدينة دبي', 'شقق على الواجهة البحرية في جزيرة الريم بأبوظبي']::text[], 'شارك في تأسيسها م. طارق سكيك ومهاب أيوب، ويضم فريقها أكثر من 50 مهندسًا معماريًا ومهندسًا ومصممًا مرخّصًا.', true
where not exists (select 1 from public.service_providers where category = 'interior' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Algedra Interior Design'));
