select 'legal', 'Al Tamimi & Company', 'Al Tamimi & Company', 'دبي', 'مركز دبي المالي العالمي', '+971 4 364 1641', 'https://www.tamimi.com', 1989, 'مكتب محاماة لديه ممارسة متخصصة في العقارات وقطاع العقارات والإنشاءات ضمن خدماته القانونية.', 'https://www.tamimi.com/offices/uae/dubai/', 'مكتب محاماة إقليمي افتتح أول مكاتبه في الإمارات بالشارقة عام 1989، ورئيسه في مركز دبي المالي العالمي. لديه ممارسة للعقارات وقطاع للعقارات والإنشاءات، ويعمل عبر 17 مكتبًا في 9 دول.', 'https://www.tamimi.com/wp-content/themes/tamimi-2020-new-design/assets/img/brands/al-tamimi.svg?=v5', 'info@tamimi.com', 'أبراج سنترال بارك، الطابق 7، شارع العملات، مركز دبي المالي العالمي، دبي', 'https://goo.gl/maps/PpU9wCKMYmpfYge79', '{}'::text[], 'يضم المكتب 360 محاميًا في 17 مكتبًا عبر 9 دول بحسب موقعه.', true
where not exists (select 1 from public.service_providers where category = 'legal' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Al Tamimi & Company'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'legal', 'Hadef & Partners', 'Hadef & Partners', 'دبي', 'وسط مدينة دبي', '+971 4 429 2999', 'https://www.hadefpartners.com', 1980, 'مكتب محاماة إماراتي يقدم خدمات قانونية في العقارات والهندسة والإنشاءات وتسوية النزاعات.', 'https://www.hadefpartners.com/', 'مكتب محاماة إماراتي أسسه الدكتور حديف الظاهري عام 1980، وله مكتبان في أبوظبي ودبي فقط. من ممارساته العقارات والهندسة والإنشاءات وتسوية النزاعات، ويذكر الموقع مشاركته في صياغة أكثر من 250 قانونًا إماراتيًا.', 'https://hadefpartners.com/media/wvghreij/logo-light.svg', 'info@hadefpartners.com', 'المبنى 3، الطابق 5، إعمار سكوير، وسط مدينة دبي، دبي', 'https://maps.app.goo.gl/WoNZXx89kcSvcYi59', '{}'::text[], 'يضم المكتب نحو 120 محاميًا في أبوظبي ودبي من الإمارات والشرق الأوسط ودول أخرى.', true
where not exists (select 1 from public.service_providers where category = 'legal' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Hadef & Partners'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'legal', 'BSA Ahmad Bin Hezeem & Associates LLC', 'BSA Ahmad Bin Hezeem & Associates LLC', 'دبي', 'مركز دبي المالي العالمي', '+971 4 528 5555', 'https://bsalaw.com', null, 'مكتب محاماة يقدم خدمات التقاضي والتحكيم والاستشارات ويخدم قطاعي العقارات والإنشاءات والهندسة.', 'https://bsalaw.com/', 'مكتب محاماة إقليمي (BSA أحمد بن هزيم ومشاركوه) له 8 مكاتب في 5 دول منها الإمارات وعُمان والسعودية. يغطي التقاضي والتحكيم والشركات، ويُدرج العقارات والإنشاءات ضمن القطاعات التي يخدمها.', 'https://bsalaw.com/wp-content/uploads/2023/09/Frame-4393.svg', 'info@bsalaw.com', 'المبنى 3، الطابق 6، منطقة البوابة، مركز دبي المالي العالمي، دبي', null, '{}'::text[], 'يضم المكتب 20 شريكًا و105 من أعضاء الفريق، ومديره الشريك جيمي حولا والشريك الأول الدكتور أحمد بن هزيم.', true
where not exists (select 1 from public.service_providers where category = 'legal' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('BSA Ahmad Bin Hezeem & Associates LLC'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'legal', 'Afridi & Angell', 'Afridi & Angell', 'دبي', 'شارع الشيخ زايد', '+971 4 330 3900', 'https://afridi-angell.com', 1975, 'يمثل المطورين والملاك والمقاولين والجهات الحكومية في جميع مراحل العمليات العقارية والإنشائية.', 'https://afridi-angell.com/our-offices/', 'مكتب محاماة تأسس في دبي عام 1975 على يد م. أ. ك. أفريدي، وافتتح مكتب الشارقة عام 1976 ومكتب أبوظبي عام 1981. يمثل فريقه العقاري المطورين الرئيسيين والفرعيين والملاك والمقاولين والجهات الحكومية.', 'https://afridi-angell.com/wp-content/uploads/2024/12/logo-new.jpg', 'dubai@afridi-angell.com', 'أبراج الإمارات، برج المكاتب، الطابق 35، شارع الشيخ زايد، دبي', 'https://www.google.com/maps/place/Afridi+%26+Angell/@25.2176,55.2798013,17z/data=!3m1!4b1!4m5!3m4!1s0x3e5f4292fc75e42f:0x1ea8ab032ef59f54!8m2!3d25.2176!4d55.28199', '{}'::text[], 'مؤسس المكتب م. أ. ك. أفريدي، والشريك المدير أمجد علي خان بحسب موقع المكتب.', true
where not exists (select 1 from public.service_providers where category = 'legal' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Afridi & Angell'));
