select 'residency', 'Virtuzone', 'Virtuzone', 'دبي', null, '+971 4 457 8200', 'https://virtuzone.com', 2009, 'تأسيس الشركات في المناطق الحرة والبر الرئيسي والأوفشور، وخدمات PRO والتأشيرة الذهبية والحسابات البنكية.', 'https://virtuzone.com/aboutus', 'تأسست عام 2009 وتصف نفسها بأنها أول متخصص مستقل في تأسيس الشركات في الإمارات. أطلقت خدمات البر الرئيسي والأوفشور عام 2016، وانضمت إلى مجموعة Ascentium عام 2025.', 'https://virtuzone.com/wp-content/uploads/2024/12/white-vz.svg', null, null, null, array['تأسيس الشركات في المناطق الحرة والبر الرئيسي والأوفشور', 'التأشيرة الذهبية والتأشيرات السياحية', 'خدمات العلاقات العامة (PRO)', 'فتح الحسابات البنكية', 'مركز Hello Business Hub بالشراكة مع اتصالات']::text[], 'تذكر الشركة أن لديها أكثر من 250 خبيراً، ويقود المجموعة الرئيس التنفيذي جورج هجيج.', true
where not exists (select 1 from public.service_providers where category = 'residency' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Virtuzone'));
