select 'residency', 'Riz & Mona Consultancy', 'Riz & Mona Consultancy', 'دبي', 'الخليج التجاري', '+971 4 558 6339', 'https://www.rizmona.com', null, 'تأسيس الشركات، وخدمات PRO والتأشيرات بما فيها الذهبية، وفتح الحسابات البنكية، والمحاسبة والضرائب.', 'https://www.rizmona.com/contact-us/', 'شركة استشارات أعمال مستقلة في الخليج التجاري بدبي، وتذكر أنها غير تابعة لأي جهة حكومية. تقدم تأسيس الشركات في الإمارات والسعودية وتسجيل المنتجات والخدمات القانونية والضريبية.', 'https://www.rizmona.com/assets/imgs/logo/logo-white.svg', 'info@rizmona.com', 'مكتب 2401، برج ذا إكستشينج، الخليج التجاري، دبي', 'https://www.google.com/maps/dir/?api=1&destination=The+Exchange+Tower,+Business+Bay,+Dubai,+UAE', array['تأسيس الشركات في البر الرئيسي والمناطق الحرة والأوفشور', 'التأشيرة الذهبية وخدمات PRO', 'فتح الحسابات البنكية', 'تسجيل العلامات التجارية', 'تسجيل المنتجات لدى وزارة الصحة']::text[], null, true
